add_action( 'add_meta_boxes', 'perfectpixel_post_meta_debugger_box', 99, 2 );

function perfectpixel_post_meta_debugger_box( $post_type, $post ) {
	if ( current_user_can( 'manage_options' ) && $post instanceof WP_Post ) {
		add_meta_box( 'perfectpixel-post-meta-debugger', 'Όλα τα custom fields', 'perfectpixel_post_meta_debugger_html', null, 'normal', 'low' );
	}
}

function perfectpixel_post_meta_debugger_html( $post ) {
	$meta = get_post_meta( $post->ID );
	if ( ! $meta ) {
		echo '<p>—</p>';
		return;
	}
	ksort( $meta );
	echo '<div style="max-height:400px;overflow:auto"><table class="widefat striped"><thead><tr><th style="width:30%">meta_key</th><th>meta_value</th></tr></thead><tbody>';
	foreach ( $meta as $key => $values ) {
		foreach ( $values as $value ) {
			$value = maybe_unserialize( $value );
			$shown = is_scalar( $value ) || null === $value ? (string) $value : print_r( $value, true );
			echo '<tr><td><code>' . esc_html( $key ) . '</code></td><td><pre style="margin:0;white-space:pre-wrap;word-break:break-all">' . esc_html( $shown ) . '</pre></td></tr>';
		}
	}
	echo '</tbody></table></div>';
}
